{
    if axis == 0 {
        out = ExpandedVector::RowVector(a);
    } else {
        // From the precondition axis <= 1 and axis != 0, we can conclude axis == 1.
        assert(axis == 1);
        out = ExpandedVector::ColumnVector(a);
    }
}

